    44→var errTimedOut = errors.New("net/http: request canceled")
    45→
    46→func tooMuchDataRequestedError(err error) bool {
    47→	// this error is only infura specific (other providers might have different error messages)
    48→	return err.Error() == "query returned more than 10000 results"
    49→}
    50→
    51→func clientTimedOutError(err error) bool {
    52→	return strings.Contains(err.Error(), errTimedOut.Error())
    53→}
