    71→// ExecutionBlock is the response kind received by the eth_getBlockByHash and
    72→// eth_getBlockByNumber endpoints via JSON-RPC.
    73→type ExecutionBlock struct {
    74→	Version int
    75→	gethtypes.Header
    76→	Hash            common.Hash              `json:"hash"`
    77→	Transactions    []*gethtypes.Transaction `json:"transactions"`
    78→	TotalDifficulty string                   `json:"totalDifficulty"`
    79→	Withdrawals     []*Withdrawal            `json:"withdrawals"`
    80→}
    81→
    82→func (e *ExecutionBlock) MarshalJSON() ([]byte, error) {
    83→	decoded := make(map[string]interface{})
    84→	encodedHeader, err := e.Header.MarshalJSON()
    85→	if err != nil {
    86→		return nil, err
    87→	}
    88→	if err := json.Unmarshal(encodedHeader, &decoded); err != nil {
    89→		return nil, err
    90→	}
    91→	decoded["hash"] = e.Hash.String()
    92→	decoded["transactions"] = e.Transactions
    93→	decoded["totalDifficulty"] = e.TotalDifficulty
    94→
    95→	if e.Version == version.Capella {
    96→		decoded["withdrawals"] = e.Withdrawals
    97→	}
    98→
    99→	return json.Marshal(decoded)
   100→}
   101→
   102→func (e *ExecutionBlock) UnmarshalJSON(enc []byte) error {
   103→	type transactionsJson struct {
   104→		Transactions []*gethtypes.Transaction `json:"transactions"`
   105→	}
   106→	type withdrawalsJson struct {
   107→		Withdrawals []*withdrawalJSON `json:"withdrawals"`
   108→	}
   109→
   110→	if err := e.Header.UnmarshalJSON(enc); err != nil {
   111→		return err
   112→	}
   113→	decoded := make(map[string]interface{})
   114→	if err := json.Unmarshal(enc, &decoded); err != nil {
   115→		return err
   116→	}
   117→	blockHashStr, ok := decoded["hash"].(string)
   118→	if !ok {
   119→		return errors.New("expected `hash` field in JSON response")
   120→	}
   121→	decodedHash, err := hexutil.Decode(blockHashStr)
   122→	if err != nil {
   123→		return err
   124→	}
   125→	e.Hash = common.BytesToHash(decodedHash)
   126→	e.TotalDifficulty, ok = decoded["totalDifficulty"].(string)
   127→	if !ok {
   128→		return errors.New("expected `totalDifficulty` field in JSON response")
   129→	}
   130→
   131→	rawWithdrawals, ok := decoded["withdrawals"]
   132→	if !ok || rawWithdrawals == nil {
   133→		e.Version = version.Bellatrix
   134→	} else {
   135→		e.Version = version.Capella
   136→		j := &withdrawalsJson{}
   137→		if err := json.Unmarshal(enc, j); err != nil {
   138→			return err
   139→		}
   140→		ws := make([]*Withdrawal, len(j.Withdrawals))
   141→		for i, wj := range j.Withdrawals {
   142→			ws[i], err = wj.ToWithdrawal()
   143→			if err != nil {
   144→				return err
   145→			}
   146→		}
   147→		e.Withdrawals = ws
   148→
   149→		edg, has := decoded["excessBlobGas"]
   150→		if has && edg != nil {
   151→			e.Version = version.Deneb
   152→		}
   153→
   154→		dgu, has := decoded["blobGasUsed"]
   155→		if has && dgu != nil {
   156→			e.Version = version.Deneb
   157→		}
   158→	}
   159→
   160→	rawTxList, ok := decoded["transactions"]
   161→	if !ok || rawTxList == nil {
   162→		// Exit early if there are no transactions stored in the json payload.
   163→		return nil
   164→	}
   165→	txsList, ok := rawTxList.([]interface{})
   166→	if !ok {
   167→		return errors.Errorf("expected transaction list to be of a slice interface type.")
   168→	}
   169→	for _, tx := range txsList {
   170→		// If the transaction is just a hex string, do not attempt to
   171→		// unmarshal into a full transaction object.
   172→		if txItem, ok := tx.(string); ok && strings.HasPrefix(txItem, "0x") {
   173→			return nil
   174→		}
   175→	}
   176→	// If the block contains a list of transactions, we JSON unmarshal
   177→	// them into a list of geth transaction objects.
   178→	txJson := &transactionsJson{}
   179→	if err := json.Unmarshal(enc, txJson); err != nil {
   180→		return err
   181→	}
   182→	e.Transactions = txJson.Transactions
   183→	return nil
   184→}
