   203→func (j *withdrawalJSON) ToWithdrawal() (*Withdrawal, error) {
   204→	w := &Withdrawal{}
   205→	b, err := json.Marshal(j)
   206→	if err != nil {
   207→		return nil, err
   208→	}
   209→	if err := w.UnmarshalJSON(b); err != nil {
   210→		return nil, err
