   215→func (w *Withdrawal) MarshalJSON() ([]byte, error) {
   216→	index := hexutil.Uint64(w.Index)
   217→	validatorIndex := hexutil.Uint64(w.ValidatorIndex)
   218→	gwei := hexutil.Uint64(w.Amount)
   219→	address := common.BytesToAddress(w.Address)
   220→	return json.Marshal(withdrawalJSON{
   221→		Index:     &index,
   222→		Validator: &validatorIndex,
   223→		Address:   &address,
   224→		Amount:    &gwei,
   225→	})
   226→}
   227→
   228→func (w *Withdrawal) UnmarshalJSON(enc []byte) error {
   229→	dec := withdrawalJSON{}
   230→	if err := json.Unmarshal(enc, &dec); err != nil {
   231→		return err
   232→	}
   233→	if dec.Index == nil {
   234→		return errors.New("missing withdrawal index")
   235→	}
   236→	if dec.Validator == nil {
   237→		return errors.New("missing validator index")
   238→	}
   239→	if dec.Amount == nil {
   240→		return errors.New("missing withdrawal amount")
   241→	}
   242→	if dec.Address == nil {
   243→		return errors.New("missing execution address")
   244→	}
   245→	*w = Withdrawal{}
   246→	w.Index = uint64(*dec.Index)
   247→	w.ValidatorIndex = primitives.ValidatorIndex(*dec.Validator)
   248→	w.Amount = uint64(*dec.Amount)
   249→	w.Address = dec.Address.Bytes()
   250→	return nil
   251→}
