   425→func (e *ExecutionPayload) MarshalJSON() ([]byte, error) {
   426→	transactions := make([]hexutil.Bytes, len(e.Transactions))
   427→	for i, tx := range e.Transactions {
   428→		transactions[i] = tx
   429→	}
   430→	baseFee := bytesutil.LittleEndianBytesToBigInt(e.BaseFeePerGas)
   431→	baseFeeHex := hexutil.EncodeBig(baseFee)
   432→	pHash := common.BytesToHash(e.ParentHash)
   433→	sRoot := common.BytesToHash(e.StateRoot)
   434→	recRoot := common.BytesToHash(e.ReceiptsRoot)
   435→	prevRan := common.BytesToHash(e.PrevRandao)
   436→	bHash := common.BytesToHash(e.BlockHash)
   437→	blockNum := hexutil.Uint64(e.BlockNumber)
   438→	gasLimit := hexutil.Uint64(e.GasLimit)
   439→	gasUsed := hexutil.Uint64(e.GasUsed)
   440→	timeStamp := hexutil.Uint64(e.Timestamp)
   441→	recipient := common.BytesToAddress(e.FeeRecipient)
   442→	logsBloom := hexutil.Bytes(e.LogsBloom)
